    private void generateFlavoredModels(Item... items) {
        for (Item item : items) {
            ResourceLocation baseName = ForgeRegistries.ITEMS.getKey(item);
            String path = baseName.getPath();

            for (int i = 1; i <= 4; i++) {
                String subModelPath = path + i;
                withExistingParent(subModelPath, "item/generated").texture("layer0", modLoc("item/" + subModelPath));
            }

            ItemModelBuilder builder = withExistingParent(path, "item/generated")
                    .texture("layer0", modLoc("item/" + path + "0"));

            for (int i = 1; i <= 4; i++) {
                builder.override()
                        .predicate(new ResourceLocation("flavor_type"), (float) i)
                        .model(getExistingFile(modLoc("item/" + path + i)))
                        .end();
            }
        }
    }
